const I18N_REV=Object.fromEntries(Object.entries(I18N).map(([k,v])=>[v,k]));
function currentLang(){return localStorage.getItem("luqma-lang")||"en"}
function translateText(t,to){if(!t)return t;const lead=t.match(/^\s*/)?.[0]||"";const trail=t.match(/\s*$/)?.[0]||"";const core=t.trim();if(to==="ar")return lead+(I18N[core]||core)+trail;return lead+(I18N_REV[core]||core)+trail}
function applyLanguage(){
 const lang=currentLang();document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";
 document.querySelectorAll("body *").forEach(el=>{if(["SCRIPT","STYLE","INPUT","TEXTAREA","OPTION"].includes(el.tagName))return;Array.from(el.childNodes).filter(n=>n.nodeType===3&&n.nodeValue.trim()).forEach(n=>n.nodeValue=translateText(n.nodeValue,lang));});
 document.querySelectorAll("input[placeholder]").forEach(el=>{const p=el.getAttribute("placeholder");if(p&&!p.includes("•"))el.setAttribute("placeholder",translateText(p,lang))});
 document.querySelectorAll("option").forEach(el=>el.textContent=translateText(el.textContent,lang));
 document.querySelectorAll(".lang-btn").forEach(b=>b.textContent=lang==="ar"?"EN":"عربي");
}
function toggleLanguage(){localStorage.setItem("luqma-lang",currentLang()==="ar"?"en":"ar");location.reload()}
function applyTheme(){
 const t=localStorage.getItem("luqma-theme")||"light";document.documentElement.dataset.theme=t;
 document.querySelectorAll(".theme-btn").forEach(b=>{b.textContent=t==="dark"?"☀":"☾";b.setAttribute("aria-label",t==="dark"?"Light mode":"Dark mode")});
}
function toggleTheme(){const n=(localStorage.getItem("luqma-theme")||"light")==="dark"?"light":"dark";localStorage.setItem("luqma-theme",n);applyTheme()}

