async function loadFoodsFromDatabase() {
  try {
    const response = await fetch("/api/foods");

    if (!response.ok) {
      throw new Error("Failed to load foods");
    }

    const databaseFoods = await response.json();

    // دمج بيانات قاعدة البيانات مع بيانات التصميم الحالية
    foods = databaseFoods.map(dbFood => {
      const designFood = foods.find(food => food.id === dbFood.id) || {};

      return {
        id: dbFood.id,
        name: dbFood.name_en,
        name_ar: dbFood.name_ar,
img: dbFood.image
  ? dbFood.image.split("/").pop()
  : "",    
    cat: dbFood.category,

        cal: dbFood.calories,
        protein: dbFood.protein,
        carbs: dbFood.carbs,
        sugar: dbFood.sugar,
        fat: dbFood.fat,

        // نحتفظ بهذه من التصميم الحالي
        emoji: designFood.emoji || "🍽️",
        color: designFood.color || "#ffffff",
        desc: designFood.desc || ""
      };
    });

    console.log("Foods loaded from database:", foods);

    // إعادة رسم الأكلات بعد تحميلها من الداتابيس
    if (typeof renderFoods === "function") {
      renderFoods();
    }

  } catch (error) {
    console.error("Database foods error:", error);

    // إذا تعذر الاتصال، تظل بيانات التصميم القديمة موجودة
    if (typeof renderFoods === "function") {
      renderFoods();
    }
  }
}

