function loadProfileSettings(){
  const input=document.getElementById("profileCalorieInput");
  const display=document.getElementById("profileCalorieDisplay");
  if(!input||!display)return;
  const saved=localStorage.getItem("luqma-calorie-goal");
  if(saved&&Number(saved)>0)input.value=saved;
  const sync=()=>{
    const value=Math.max(1,Math.round(Number(input.value)||0));
    display.textContent=value?value.toLocaleString("en-US"):"—";
  };
  input.addEventListener("input",sync);
  sync();
}
