async function loadDailyMeals() {
  const container = document.getElementById("dailyMealsList");

  // إذا مو في صفحة My Day، ما يسوي شيء
  if (!container) return;
 const userId = localStorage.getItem("luqma-user-id");

 if (!userId) {
  window.location.href = "login.html";
  return;
 }
  try {
 const response = await fetch(`/api/daily-meals/${userId}`);
    if (!response.ok) {
      throw new Error("Failed to load daily meals");
    }

    const meals = await response.json();
let calories = 0;
let protein = 0;
let carbs = 0;
let fat = 0;
let sugar = 0;

meals.forEach(meal => {
  calories += meal.calories * meal.quantity;
  protein += meal.protein * meal.quantity;
  carbs += meal.carbs * meal.quantity;
  fat += meal.fat * meal.quantity;
  sugar += meal.sugar * meal.quantity;
});

document.getElementById("totalCalories").textContent = Math.round(calories);
document.getElementById("totalProtein").textContent = Math.round(protein) + "g";
document.getElementById("totalCarbs").textContent = Math.round(carbs) + "g";
document.getElementById("totalFat").textContent = Math.round(fat) + "g";
document.getElementById("totalSugar").textContent = Math.round(sugar) + "g";
    container.innerHTML = meals.map(meal => {

      const name =
        currentLang() === "ar"
          ? meal.name_ar
          : meal.name_en;

      const totalCalories =
        Math.round(meal.calories * meal.quantity);

      const totalProtein =
        Math.round(meal.protein * meal.quantity);

      return `
        <div class="meal-block">

          <div class="meal-time">
            ${meal.quantity}×
          </div>

          <article>

            <div class="meal-emoji">
              <img
                src="${meal.image}"
                alt="${name}"
                style="width:70px;height:70px;object-fit:cover;border-radius:14px;"
              >
            </div>

            <div>
              <span class="eyebrow">
${currentLang() === "ar"
  ? (I18N[meal.meal_type] || meal.meal_type)
  : meal.meal_type.toUpperCase()
}              </span>

              <h3>${name}</h3>

              <p>
               ${currentLang() === "ar"
  ? `${totalCalories} سعرة · ${totalProtein}غ بروتين`
  : `${totalCalories} kcal · ${totalProtein}g protein`
}
              </p>
            </div>

<button
  class="delete-meal-btn"
  onclick="deleteMeal(${meal.id})"
  title="Delete meal"
    style="position:absolute; left:20px;"

>
  ❌
</button>
          </article>
        </div>
      `;
    }).join("");

  } catch (error) {
    console.error("MY DAY ERROR:", error);

    container.innerHTML = `
      <p>Could not load your meals.</p>
    `;
  }
}

