async function deleteMeal(mealId) {
  try {
    const response = await fetch(`/api/daily-meals/${mealId}`, {
      method: "DELETE"
    });

    if (!response.ok) {
      throw new Error("Failed to delete meal");
    }

    toast(
  currentLang() === "ar"
    ? "❌ تم حذف الوجبة!"
    : "❌ Meal removed!"
);

    loadDailyMeals();

  } catch (error) {
    console.error("DELETE MEAL ERROR:", error);
    toast("Could not remove meal");
  }
}
function updateLoginButton() {
  const userId = localStorage.getItem("luqma-user-id");
  const lang = localStorage.getItem("luqma-lang") || "en";

  document.querySelectorAll(".login-btn").forEach(btn => {

    if (userId) {
      btn.textContent = lang === "ar" ? "تسجيل الخروج " : "LOG OUT ";

      btn.onclick = function(e) {
        e.preventDefault();
        localStorage.removeItem("luqma-user-id");
        window.location.href = "login.html";
      };

    } else {
      btn.textContent = lang === "ar" ? "تسجيل الدخول " : "LOG IN ";

      btn.onclick = function() {
        window.location.href = "login.html";
      };
    }
  });
}

document.addEventListener("DOMContentLoaded", updateLoginButton);